85:     audio.master.connect(audio.context.destination);
86:     audio.drive = audio.context.createWaveShaper();
87:     const curve = new Float32Array(4096);
88:     for (let i = 0; i < curve.length; i += 1) {
89:       const x = (i * 2) / curve.length - 1;
90:       curve[i] = Math.tanh(x * 5);
91:     }
92:     audio.drive.curve = curve; audio.drive.oversample = '4x'; audio.drive.connect(audio.master);
93:   }
