97:   audio.musicTimer = window.setInterval(() => {
98:     if (!world.running || !audio.context) return;
99:     const ctx = audio.context;
100:     const now = ctx.currentTime;
101:     const step = audio.musicStep++ % riff.length;
102:     if ([0, 4, 8, 12].includes(step)) {
103:       const kick = ctx.createOscillator(); const volume = ctx.createGain();
104:       kick.type = 'sine'; kick.frequency.setValueAtTime(115, now); kick.frequency.exponentialRampToValueAtTime(38, now + 0.12);
105:       volume.gain.setValueAtTime(0.28, now); volume.gain.exponentialRampToValueAtTime(0.001, now + 0.14);
106:       kick.connect(volume); volume.connect(audio.master); kick.start(now); kick.stop(now + 0.15);
107:     } else if ([2, 6, 10, 14].includes(step)) {
108:       const snare = ctx.createOscillator(); const volume = ctx.createGain();
109:       snare.type = 'triangle'; snare.frequency.value = 175;
110:       volume.gain.setValueAtTime(0.12, now); volume.gain.exponentialRampToValueAtTime(0.001, now + 0.08);
111:       snare.connect(volume); volume.connect(audio.master); snare.start(now); snare.stop(now + 0.09);
112:     }
113:     if (step % 2 === 0) {
114:       const root = riff[step];
115:       [root, root * 1.5].forEach((frequency) => {
