117:         osc.type = 'sawtooth'; osc.frequency.value = frequency;
118:         filter.type = 'lowpass'; filter.frequency.value = 420;
119:         gain.gain.setValueAtTime(0.095, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);
