222: function applyZombieAsset(zombie) {
223:   if (!zombieAsset.root || !window.THREE.SkeletonUtils) return false;
224:   const replacement = THREE.SkeletonUtils.clone(zombieAsset.root);
225:   replacement.traverse((part) => {
226:     if (!part.isMesh) return;
227:     part.castShadow = true;
228:     part.receiveShadow = true;
229:     const cloneMaterial = (material) => {
230:       const instance = material.clone();
231:       if (instance.color) instance.color.multiplyScalar(1.12);
232:       if (instance.color && zombie.variant.tint !== 0xffffff) instance.color.multiply(new THREE.Color(zombie.variant.tint));
233:       if (instance.emissive && instance.emissive.getHex() !== 0) instance.emissive.multiplyScalar(1.1);
234:       if (instance.emissive) instance.userData.baseEmissive = instance.emissive.clone();
235:       return instance;
236:     };
237:     part.material = Array.isArray(part.material) ? part.material.map(cloneMaterial) : cloneMaterial(part.material);
238:   });
239:   replacement.updateWorldMatrix(true, true);
240:   const bounds = new THREE.Box3().setFromObject(replacement);
241:   const size = bounds.getSize(new THREE.Vector3());
242:   if (!Number.isFinite(size.y) || size.y < 0.1) return false;
243:   const center = bounds.getCenter(new THREE.Vector3());
244:   const scale = (1.65 * zombie.variant.modelScale) / size.y;
245:   replacement.scale.setScalar(scale);
246:   replacement.position.set(-center.x * scale, -bounds.min.y * scale, -center.z * scale);
247:   const root = new THREE.Group();
248:   root.add(replacement);
249:   addZombieHealthBar(zombie, root);
250:   if (zombie.model) {
251:     scene.remove(zombie.model);
252:     zombie.model.traverse((part) => { if (part.geometry) part.geometry.dispose(); });
253:   }
254:   scene.add(root);
255:   zombie.model = root;
256:   zombie.limbs = [];
257:   zombie.mixer = new THREE.AnimationMixer(replacement);
258:   if (zombieAsset.clips.length) {
259:     zombie.action = zombie.mixer.clipAction(zombieAsset.clips[0]);
260:     zombie.action.setLoop(THREE.LoopRepeat, Infinity);
261:     zombie.action.play();
262:   }
263:   syncEntity(zombie);
264:   return true;
265: }
266: function loadZombieAsset() {
