268:     if (!THREE.GLTFLoader) {
269:       zombieAsset.failed = true;
270:       console.warn('GLTFLoader unavailable; using procedural zombies.');
271:       resolve(false);
272:       return;
273:     }
274:     const loader = new THREE.GLTFLoader();
275:     loader.load('public/models/zombie.glb', (gltf) => {
276:       zombieAsset.root = gltf.scene;
277:       zombieAsset.clips = gltf.animations || [];
278:       for (const zombie of world.zombies) applyZombieAsset(zombie);
279:       resolve(true);
280:     }, undefined, (error) => {
281:       zombieAsset.failed = true;
282:       console.warn('Zombie model failed to load; using procedural fallback.', error);
283:       resolve(false);
284:     });
285:   });
286:   return zombieAsset.ready;
