304: function updateZombieHealthBar(zombie) {
305:   if (!zombie.healthBar) return;
306:   const ratio = clamp(zombie.hp / zombie.maxHp, 0, 1);
307:   const { fill, width } = zombie.healthBar;
308:   fill.visible = ratio > 0;
309:   fill.scale.x = width * ratio;
310:   fill.position.x = -(width * (1 - ratio)) / 2;
311:   fill.material.color.setHex(zombie.isBoss ? 0xff4b5c : ratio > 0.55 ? 0x75d477 : ratio > 0.25 ? 0xe7bd4c : 0xe34e4e);
312: }
