617: function updatePlayer(dt) {
618:   const player = world.player;
619:   let dx = 0; let dy = 0;
620:   if (input.keys.has('w') || input.keys.has('arrowup')) dy -= 1;
621:   if (input.keys.has('s') || input.keys.has('arrowdown')) dy += 1;
622:   if (input.keys.has('a') || input.keys.has('arrowleft')) dx -= 1;
623:   if (input.keys.has('d') || input.keys.has('arrowright')) dx += 1;
624:   if (input.touchStick.active) { dx += input.touchStick.x; dy += input.touchStick.y; }
625:   const length = Math.hypot(dx, dy) || 1;
626:   player.x = clamp(player.x + dx / length * player.speed * dt, 20, world.width - 20);
627:   player.y = clamp(player.y + dy / length * player.speed * dt, 20, world.height - 20);
628:   if (player.regen > 0 && player.hp < player.maxHp) player.hp = Math.min(player.maxHp, player.hp + player.regen * dt);
629:   player.orbitTimer = Math.max(0, player.orbitTimer - dt);
630:   let target = null; let targetDistance = 650;
631:   for (const zombie of world.zombies) {
632:     const distance = dist(player.x, player.y, zombie.x, zombie.y);
633:     if (distance < targetDistance) { target = zombie; targetDistance = distance; }
634:   }
635:   if (target) {
636:     player.angle = Math.atan2(target.y - player.y, target.x - player.x);
637:     player.fireCooldown -= dt;
638:     if (player.fireCooldown <= 0) { fireBullet(); player.fireCooldown = player.fireRate; }
639:   } else player.fireCooldown = Math.min(player.fireCooldown, 0);
640:   player.model.rotation.y = Math.PI / 2 - player.angle;
641:   syncEntity(player);
642:   player.bombCooldown = Math.max(0, player.bombCooldown - dt);
643:   if (input.bomb) { input.bomb = false; if (player.bombCooldown <= 0) throwBomb(); }
644:   if (player.invuln > 0) player.invuln -= dt;
645:   if (player.gunFlash > 0) player.gunFlash -= dt;
646:   updateWeaponLabel();
647: }
