666: function updateCombat(dt, time) {
667:   for (let i = world.zombies.length - 1; i >= 0; i -= 1) {
668:     const z = world.zombies[i];
669:     const dx = world.player.x - z.x; const dy = world.player.y - z.y; const len = Math.hypot(dx, dy) || 1;
670:     z.x += dx / len * z.speed * dt; z.y += dy / len * z.speed * dt;
671:     z.model.rotation.y = Math.atan2(dx, dy);
672:     z.phase += dt * 5;
673:     z.model.position.copy(toScene(z.x, z.y));
674:     z.model.position.y = Math.abs(Math.sin(z.phase)) * 0.035;
675:     if (z.mixer) z.mixer.update(dt);
676:     else z.limbs.forEach((limb, index) => { limb.rotation.z += Math.sin(time * 0.008 + index) * 0.0015; });
677:     const orbit = world.player.orbitModel;
678:     if (orbit) { orbit.visible = world.player.orbitLevel > 0; orbit.rotation.y += dt * (2.1 + world.player.orbitLevel * 0.35); }
679:     if (world.player.orbitLevel > 0 && world.player.orbitTimer <= 0 && dist(z.x, z.y, world.player.x, world.player.y) < 70 + world.player.orbitLevel * 15) {
680:       damageZombie(z, 18 + world.player.orbitLevel * 13); z.hitFlash = 0.08; world.player.orbitTimer = 0.22;
681:       if (z.hp <= 0) {
682:         defeatZombie(z, i);
683:         continue;
684:       }
685:     }
686:     if (z.hitFlash > 0) {
687:       z.hitFlash -= dt;
688:       z.model.traverse((part) => {
689:         if (!part.isMesh) return;
690:         const materials = Array.isArray(part.material) ? part.material : [part.material];
691:         materials.forEach((material) => material.emissive?.setHex(0x756f61));
692:       });
693:     } else z.model.traverse((part) => {
694:       if (!part.isMesh) return;
695:       const materials = Array.isArray(part.material) ? part.material : [part.material];
696:       materials.forEach((material) => material.emissive?.copy(material.userData.baseEmissive || new THREE.Color(0x000000)));
697:     });
698:     if (dist(z.x, z.y, world.player.x, world.player.y) < z.radius + world.player.radius && world.player.invuln <= 0) {
699:       world.player.hp = Math.max(0, world.player.hp - Math.max(1, z.damage - world.player.armor));
700:       world.player.invuln = 0.65;
701:       if (world.player.hp <= 0) finishGame();
702:     }
703:   }
704: }
